svg.script:
//
(async function () {
  // Script is on the SVG root (not inside foreignObject) so it actually runs.
  // jsDelivr serves .html as text/plain — must load via blob type text/html to RENDER.
  function $(id) {
    return document.getElementById(id);
  }
  function setStatus(t) {
    var s = $("status");
    if (s) s.textContent = t;
  }

  var host = "cdn.jsdelivr.net";
  try {
    if (location.hostname && /jsdelivr|b-cdn\.net/i.test(location.hostname)) {
      host = location.hostname;
    }
  } catch (e) {}

  var base = "https://" + host + "/gh/Mo9nikeypurple/skool@main/";
  var pageUrl = base + "index.html?t=" + Date.now();

  try {
    setStatus("Fetching " + pageUrl + " …");
    var res = await fetch(pageUrl, { cache: "no-store", mode: "cors" });
    if (!res.ok) throw new Error("HTTP " + res.status);
    var html = await res.text();
    if (!html || html.length < 100) throw new Error("Empty index.html");

    // Force a full document
    if (!/<!DOCTYPE/i.test(html) && !/<html/i.test(html)) {
      html = "<!DOCTYPE html><html><head></head><body>" + html + "</body></html>";
    }

    // <base> so relative assets resolve on this CDN host
    if (!/<base\s/i.test(html)) {
      html = html.replace(/<head([^>]*)>/i, function (m, a) {
        return "<head" + a + ">\n<base href=\"" + base + "\">";
      });
    }

    // CRITICAL: text/html so the browser RENDers instead of showing source text
    var blob = new Blob([html], { type: "text/html;charset=utf-8" });
    var blobUrl = URL.createObjectURL(blob);

    var mount = $("mount");
    if (!mount) throw new Error("No #mount");

    var iframe = document.createElementNS("http://www.w3.org/1999/xhtml", "iframe");
    iframe.setAttribute("src", blobUrl);
    iframe.setAttribute("allow", "fullscreen; autoplay; encrypted-media; clipboard-read; clipboard-write");
    iframe.setAttribute("style", "position:fixed;top:0;left:0;width:100%;height:100%;border:0;margin:0;padding:0;background:#000;");

    mount.innerHTML = "";
    mount.appendChild(iframe);
  } catch (err) {
    var msg = (err && err.message) ? err.message : String(err);
    setStatus("Failed: " + msg + " — Try opening " + pageUrl + " (may show as text on jsDelivr; use GitHub Pages for best results)");
  }
})();
//
